1	<!DOCTYPE html>
2	<html lang="zh-Hant">
3	<head>
4	<meta charset="UTF-8">
5	<meta name="viewport" content="width=device-width, initial-scale=1.0">
6	<title>來賓名單｜大樹教練活動系統</title>
7	<link href="https://fonts.googleapis.com/css2?family=Noto+Sans+TC:wght@500;700;900&display=swap" rel="stylesheet">
8	<style>
9	  :root { --gold:#c8a96e; --dark:#0a0a0a; --dark2:#141414; --line:rgba(200,169,110,.3); }
10	  * { margin:0; padding:0; box-sizing:border-box; }
11	  body { font-family:'Noto Sans TC', sans-serif; background:var(--dark); color:#fff; padding:28px 16px 60px; }
12	  .wrap { max-width:900px; margin:0 auto; }
13	  h1 { font-size:26px; font-weight:900; margin-bottom:4px; }
14	  h1 span { color:var(--gold); }
15	  .total { font-size:18px; color:rgba(255,255,255,.75); margin-bottom:24px; }
16	  .events { display:flex; flex-wrap:wrap; gap:10px; margin-bottom:26px; }
17	  .chip {
18	    text-decoration:none; padding:10px 18px; border-radius:999px; font-size:17px; font-weight:700;
19	    color:#fff; background:#1c1c1c; border:1px solid var(--line);
20	  }
21	  .chip.active, .chip:hover { background:var(--gold); color:var(--dark); }
22	  .chip .n { opacity:.75; font-weight:900; }
23	  .export, .notify-btn {
24	    display:inline-block; text-decoration:none; margin-bottom:22px; padding:11px 20px;
25	    font-size:17px; font-weight:900; color:var(--dark); background:var(--gold); border-radius:8px;
26	  }
27	  .notify-btn { background:#06C755; color:#fff; margin-left:10px; }
28	  .current-box {
29	    background:#1c1c1c; border:1px solid var(--line); border-radius:10px; padding:16px 18px; margin-bottom:22px;
30	  }
31	  .current-box .label { font-size:15px; color:rgba(255,255,255,.6); font-weight:700; margin-bottom:8px; }
32	  .current-box .now { font-size:19px; font-weight:900; color:var(--gold); margin-bottom:12px; }
33	  .current-box form { display:flex; gap:10px; flex-wrap:wrap; }
34	  .current-box select { flex:1; min-width:200px; padding:10px 12px; font-size:16px; border-radius:8px;
35	    border:1px solid var(--line); background:#0a0a0a; color:#fff; }
36	  .current-box button { padding:10px 20px; font-size:16px; font-weight:900; border-radius:8px; border:none;
37	    background:var(--gold); color:var(--dark); cursor:pointer; }
38	  .tbl { width:100%; overflow-x:auto; }
39	  table { width:100%; border-collapse:collapse; font-size:17px; }
40	  th { text-align:left; color:var(--gold); font-size:16px; font-weight:700; padding:10px 12px; border-bottom:1px solid var(--line); white-space:nowrap; }
41	  td { padding:12px; border-bottom:1px solid rgba(255,255,255,.08); vertical-align:top; }
42	  td.name { font-weight:900; font-size:18px; white-space:nowrap; }
43	  td.phone { font-variant-numeric:tabular-nums; white-space:nowrap; }
44	  .badge { display:inline-block; background:#1c1c1c; border:1px solid var(--line); color:var(--gold);
45	           border-radius:6px; padding:2px 8px; font-size:14px; font-weight:700; }
46	  .line-yes { color:#06C755; font-weight:900; }
47	  .line-no { color:rgba(255,255,255,.35); }
48	  .empty { padding:40px 0; text-align:center; color:rgba(255,255,255,.5); font-size:18px; }
49	</style>
50	</head>
51	<body>
52	  <div class="wrap">
53	    <h1>來賓名單<span>｜大樹教練活動系統</span></h1>
54	    <p class="total">目前累計 <strong style="color:var(--gold)">{{ attendees|length }}</strong> 位來賓{% if selected %}（已篩選）{% endif %}</p>
55	
56	    <div class="current-box">
57	      <div class="label">📌 固定 QR 立牌（/checkin）目前導向</div>
58	      <div class="now">{{ current_event.name if current_event else '尚未設定——QR掃了會顯示「目前沒有進行中的活動」' }}</div>
59	      <form method="POST" action="/admin/set-current?key={{ admin_key }}">
60	        <select name="event">
61	          {% for e in events %}
62	          <option value="{{ e.slug }}" {{ 'selected' if current_event and current_event.slug == e.slug else '' }}>{{ e.name }}{% if e.event_date %}（{{ e.event_date }}）{% endif %}</option>
63	          {% endfor %}
64	        </select>
65	        <button type="submit">切換為目前活動</button>
66	      </form>
67	    </div>
68	
69	    <div class="events">
70	      <a class="chip {{ '' if selected else 'active' }}" href="?key={{ admin_key }}">全部來賓</a>
71	      {% for e in events %}
72	      <a class="chip {{ 'active' if selected == e.slug else '' }}" href="?key={{ admin_key }}&event={{ e.slug }}">
73	        {{ e.name }} <span class="n">{{ e.signup_count }}人</span>
74	      </a>
75	      {% endfor %}
76	    </div>
77	
78	    <a class="export" href="/admin/export.csv?key={{ admin_key }}">⬇ 下載名單（Excel 可開）</a>
79	    <a class="notify-btn" href="/admin/notify?key={{ admin_key }}">💬 發送通知</a>
80	
81	    <div class="tbl">
82	      <table>
83	        <tr><th>姓名</th><th>手機</th><th>公司／職稱</th><th>參加過的活動</th><th>首次留資料</th><th>LINE可通知</th></tr>
84	        {% for a in attendees %}
85	        <tr>
86	          <td class="name">{{ a.name }}</td>
87	          <td class="phone">{{ a.phone }}</td>
88	          <td>{{ a.company_title or '—' }}</td>
89	          <td><span class="badge">{{ a.event_count }} 場</span> {{ a.attended_events }}</td>
90	          <td>{{ a.created_at }}</td>
91	          <td>{% if a.line_bound %}<span class="line-yes">✓ 已綁定</span>{% else %}<span class="line-no">未綁定</span>{% endif %}</td>
92	        </tr>
93	        {% endfor %}
94	      </table>
95	      {% if not attendees %}<div class="empty">目前還沒有來賓資料</div>{% endif %}
96	    </div>
97	  </div>
98	</body>
99	</html>
