1	<!DOCTYPE html>
2	<html lang="zh-Hant">
3	<head>
4	<meta charset="UTF-8">
5	<meta name="viewport" content="width=device-width, initial-scale=1.0">
6	<title>發送通知｜大樹教練活動系統</title>
7	<link href="https://fonts.googleapis.com/css2?family=Noto+Sans+TC:wght@500;700;900&display=swap" rel="stylesheet">
8	<style>
9	  :root { --gold:#c8a96e; --dark:#0a0a0a; --dark2:#141414; --line:rgba(200,169,110,.3); }
10	  * { margin:0; padding:0; box-sizing:border-box; }
11	  body { font-family:'Noto Sans TC', sans-serif; background:var(--dark); color:#fff; padding:28px 16px 60px; }
12	  .wrap { max-width:560px; margin:0 auto; }
13	  h1 { font-size:26px; font-weight:900; margin-bottom:4px; }
14	  h1 span { color:var(--gold); }
15	  .back { display:inline-block; margin-bottom:20px; color:rgba(255,255,255,.5); text-decoration:none; font-size:15px; }
16	  label { display:block; font-size:18px; font-weight:700; color:var(--gold); margin:20px 0 8px; }
17	  select, textarea {
18	    width:100%; padding:14px; font-size:18px; font-family:inherit; font-weight:500;
19	    background:#0f0f0f; color:#fff; border:1px solid var(--line); border-radius:10px; outline:none;
20	  }
21	  textarea { min-height:140px; resize:vertical; line-height:1.6; }
22	  select:focus, textarea:focus { border-color:var(--gold); }
23	  .hint { font-size:15px; color:rgba(255,255,255,.5); margin-top:8px; }
24	  button {
25	    width:100%; margin-top:24px; padding:16px; font-size:20px; font-weight:900; font-family:inherit;
26	    color:var(--dark); background:var(--gold); border:none; border-radius:10px; cursor:pointer; letter-spacing:4px;
27	  }
28	  button:hover { filter:brightness(1.12); }
29	  .result {
30	    margin-top:24px; padding:18px; border-radius:10px; background:#0f2a1a; border:1px solid rgba(6,199,85,.4);
31	    font-size:17px; line-height:1.8;
32	  }
33	  .result b { color:#06C755; font-size:20px; }
34	</style>
35	</head>
36	<body>
37	  <div class="wrap">
38	    <a class="back" href="/admin?key={{ admin_key }}">← 回名單</a>
39	    <h1>發送通知<span>｜精準分眾</span></h1>
40	
41	    {% if result %}
42	    <div class="result">
43	      這場活動共 <b>{{ result.total }}</b> 位可通知的來賓<br>
44	      成功送出 <b>{{ result.sent }}</b> 則{% if result.failed %}，失敗 {{ result.failed }} 則{% endif %}
45	    </div>
46	    {% endif %}
47	
48	    <form method="POST">
49	      <label>選擇活動（只發給參加過這場的人）</label>
50	      <select name="event" required>
51	        <option value="">請選擇</option>
52	        {% for e in events %}
53	        <option value="{{ e.slug }}">{{ e.name }}（{{ e.event_date or '' }}）— {{ e.line_bound_count or 0 }}/{{ e.signup_count }} 人可通知</option>
54	        {% endfor %}
55	      </select>
56	
57	      <label>訊息內容</label>
58	      <textarea name="message" placeholder="例：大樹教練提醒您，下次活動 XX月XX日 歡迎再來參加！" required></textarea>
59	      <p class="hint">只會發給「已加好友＋已傳過問候」的人，人數看上面選單括號裡的比例</p>
60	
61	      <button type="submit">送出通知</button>
62	    </form>
63	  </div>
64	</body>
65	</html>
